    /** Haftarah for the given parsha in the given custom, or null if unknown. */
    public static List<Reference> forParsha(Parsha p, Custom c) {
        Map<Custom, List<Reference>> m = ALL.get(p);
        return m == null ? null : m.get(c);
    }
